# World of 365 by the user's list: macro -> diocese/group -> province -> cities.
# City tuple: (name, lat, lon, tier 1..4, CK3 name aliases 'a|b', flags: 'p' = sea port)
DIO=[]; PROV=[]
def D(key,label,full,macro,realm,player,kind,reach=330): DIO.append(dict(key=key,label=label,full=full,macro=macro,realm=realm,p=player,kind=kind,reach=reach))
def P(name,cities,hints,reach=None,p=None,bits=None):
    d=DIO[-1]; PROV.append(dict(n=name,dio=len(DIO)-1,cities=cities,hints=hints,reach=reach or d['reach'],p=d['p'] if p is None else p,
                               bits=bits or (1 if d['kind']=='R' else 2)))
